import os
import base64
from io import BytesIO
from fastapi import FastAPI
from pydantic import BaseModel
from PIL import Image
import threading
from contextlib import contextmanager
import json

# Import CUDA-related modules only in the main thread
cuda_initialized = False
cuda_lock = threading.Lock()

@contextmanager
def cuda_context():
    """Context manager to handle CUDA context in a thread-safe way"""
    global cuda_initialized
    
    import pycuda.autoinit
    import pycuda.driver as cuda
    import torch
    
    with cuda_lock:
        if not cuda_initialized:
            # Initialize CUDA context
            cuda.init()
            # Create a context
            device = cuda.Device(0)
            ctx = device.make_context()
            # Initialize PyTorch CUDA
            if torch.cuda.is_available():
                torch.cuda.init()
                _ = torch.empty(1).cuda()
            cuda_initialized = True
            print("CUDA context initialized")
        
        try:
            yield
        finally:
            # Don't pop the context, keep it alive
            pass

app = FastAPI()

class RelightRequest(BaseModel):
    image_base64: str
    light_pos: list
    steps: int
    prompt: str

@app.post("/relight")
def relight_image(req: RelightRequest):
    try:
        # Create a new CUDA context for this request
        with cuda_context():
            # decode input image
            print(req.image_base64[:30])
            img_bytes = base64.b64decode(req.image_base64)
            img = Image.open(BytesIO(img_bytes))

            # Import here to ensure CUDA is initialized first
            from pipeline_relighting import run_pipeline_programmatically
            
            # run your existing pipeline
            saved_paths = run_pipeline_programmatically(
                img,
                req.light_pos,
                req.steps,
                req.prompt
            )

            # The function returns a list of saved paths, we need the final output image
            if not saved_paths:
                raise ValueError("No output files were generated by the pipeline")
                
            # Assuming the last path in the list is the final output image
            output_path = saved_paths[-1]
            return {"output_path": output_path}
            
    except Exception as e:
        print(f"Error in relight_image: {str(e)}")
        import traceback
        traceback.print_exc()
        raise

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=5000)